<?php
namespace App\Domains\Marketplace\Http\Controllers;
use App\Domains\Marketplace\Models\{Extension,ExtensionVersion,Installation}; use App\Domains\Marketplace\Services\MarketplaceService; use App\Domains\Platform\Contracts\TenantContext; use Illuminate\Http\{JsonResponse,Request};
class MarketplaceController { public function __construct(private readonly MarketplaceService $market,private readonly TenantContext $tenant){} private function allow(Request $r,string $p):void{$r->user()->hasPermission($p)||abort(403);} public function index(Request $r):JsonResponse{$this->allow($r,'marketplace.view');return response()->json(['data'=>Extension::query()->where('status','published')->with('versions')->paginate(25)]);} public function publish(Request $r):JsonResponse{$this->allow($r,'marketplace.manage');$d=$r->validate(['slug'=>['required','alpha_dash','max:120'],'name'=>['required','string'],'publisher'=>['required','string'],'extension_type'=>['required','string'],'description'=>['nullable','string'],'license'=>['nullable','string'],'manifest'=>['required','array']]);return response()->json(['data'=>Extension::query()->create($d)],201);} public function version(Request $r,string $extension):JsonResponse{$this->allow($r,'marketplace.manage');$e=Extension::query()->findOrFail($extension);$d=$r->validate(['version'=>['required','string'],'platform_constraint'=>['nullable','string'],'dependencies'=>['nullable','array'],'artifact_path'=>['nullable','string'],'checksum'=>['nullable','string'],'signature'=>['nullable','string']]);return response()->json(['data'=>$e->versions()->create($d)],201);} public function install(Request $r,string $extension,string $version):JsonResponse{$this->allow($r,'marketplace.manage');$e=Extension::query()->findOrFail($extension);$v=$e->versions()->whereKey($version)->firstOrFail();return response()->json(['data'=>$this->market->install($this->tenant->id(),$e,$v)],201);} public function installed(Request $r):JsonResponse{$this->allow($r,'marketplace.view');return response()->json(['data'=>Installation::query()->where('tenant_id',$this->tenant->id())->with(['extension','version'])->get()]);} }
